const e=[{id:"pron-ich",category:"pronoun",de:"ich",en:["I"],hi:["मैं"],hiTranslit:"main",ipa:"ɪç",deva:"इख़्",level:"A1",illustration:"pron-ich",type:"personal",person:1,number:"sg",forms:{nom:"ich",akk:"mich",dat:"mir",gen:"meiner"},notes:'Only capitalised at the start of a sentence — unlike English "I".',examples:[{de:[{t:"Ich",g:0},{t:"lerne",g:1},{t:"Deutsch",g:2}],en:[{t:"I",g:0},{t:"am learning",g:1},{t:"German",g:2}],hi:[{t:"मैं",g:0},{t:"जर्मन",g:2},{t:"सीखता हूँ",g:1}],hiTranslit:"main German seekhta hoon",note:"German and English keep the verb in position 2; Hindi sends it to the end."}]},{id:"pron-du",category:"pronoun",de:"du",en:["you (informal, singular)"],hi:["तू","तुम"],hiTranslit:"too / tum",ipa:"duː",deva:"डू",level:"A1",illustration:"pron-du",type:"personal",person:2,number:"sg",formality:"informal",forms:{nom:"du",akk:"dich",dat:"dir",gen:"deiner"},notes:'Informal "du" is for family, friends, and children — matched by Hindi तू/तुम, a distinction English "you" no longer makes.',examples:[{de:[{t:"Du",g:0},{t:"wohnst",g:1},{t:"in Berlin",g:2}],en:[{t:"You",g:0},{t:"live",g:1},{t:"in Berlin",g:2}],hi:[{t:"तुम",g:0},{t:"बर्लिन में",g:2},{t:"रहते हो",g:1}],hiTranslit:"tum Berlin mein rehte ho",note:"German and English place the verb right after the subject; Hindi moves it to the very end of the clause."}]},{id:"pron-er",category:"pronoun",de:"er",en:["he","it (for a masculine noun)"],hi:["वह"],hiTranslit:"vah",ipa:"eːɐ̯",deva:"एअ",level:"A1",illustration:"pron-er",type:"personal",person:3,number:"sg",gender:"m",forms:{nom:"er",akk:"ihn",dat:"ihm",gen:"seiner"},notes:'Replaces any masculine-gender noun, not only male people — der Tisch ("the table") becomes er.',examples:[{de:[{t:"Er",g:0},{t:"arbeitet",g:1},{t:"jeden Tag",g:2}],en:[{t:"He",g:0},{t:"works",g:1},{t:"every day",g:2}],hi:[{t:"वह",g:0},{t:"हर दिन",g:2},{t:"काम करता है",g:1}],hiTranslit:"vah har din kaam karta hai",note:'German marks grammatical gender on the pronoun itself; English "he" tracks only natural gender.'}]},{id:"pron-sie-sg-f",category:"pronoun",de:"sie",en:["she","it (for a feminine noun)"],hi:["वह"],hiTranslit:"vah",ipa:"ziː",deva:"ज़ी",level:"A1",illustration:"pron-sie-sg-f",type:"personal",person:3,number:"sg",gender:"f",forms:{nom:"sie",akk:"sie",dat:"ihr",gen:"ihrer"},notes:'Also replaces any feminine noun, such as die Zeitung ("the newspaper") — gender lives in the pronoun, not the person.',examples:[{de:[{t:"Sie",g:0},{t:"liest",g:1},{t:"die Zeitung",g:2}],en:[{t:"She",g:0},{t:"reads",g:1},{t:"the newspaper",g:2}],hi:[{t:"वह",g:0},{t:"अख़बार",g:2},{t:"पढ़ती है",g:1}],hiTranslit:"vah akhbaar padhti hai",note:'Nominative "sie" is identical for "she" and "they" — only the verb ending tells them apart.'}]},{id:"pron-es",category:"pronoun",de:"es",en:["it"],hi:["यह","वह"],hiTranslit:"yah / vah",ipa:"ɛs",deva:"एस्",level:"A1",illustration:"pron-es",type:"personal",person:3,number:"sg",gender:"n",forms:{nom:"es",akk:"es",dat:"ihm",gen:"seiner"},notes:"Stands in for neuter nouns like das Kind, and also appears as a dummy subject in weather expressions with no real referent at all.",examples:[{de:[{t:"Es"},{t:"regnet",g:0},{t:"heute",g:1}],en:[{t:"It"},{t:"is raining",g:0},{t:"today",g:1}],hi:[{t:"आज",g:1},{t:"बारिश हो रही है",g:0}],hiTranslit:"aaj baarish ho rahi hai",note:'German and English both need a dummy subject "es/it" for weather; Hindi needs no subject placeholder at all.'}]},{id:"pron-wir",category:"pronoun",de:"wir",en:["we"],hi:["हम"],hiTranslit:"hum",ipa:"viːɐ̯",deva:"वीअ",level:"A1",illustration:"pron-wir",type:"personal",person:1,number:"pl",forms:{nom:"wir",akk:"uns",dat:"uns",gen:"unser"},notes:"The 1st-person-plural pronoun; German marks it with a -en verb ending much as Hindi verb agreement does.",examples:[{de:[{t:"Wir",g:0},{t:"lernen",g:1},{t:"zusammen",g:2}],en:[{t:"We",g:0},{t:"learn",g:1},{t:"together",g:2}],hi:[{t:"हम",g:0},{t:"साथ में",g:2},{t:"सीखते हैं",g:1}],hiTranslit:"hum saath mein seekhte hain",note:"German and English keep subject-verb-adverb order; Hindi places the adverb before the clause-final verb."}]},{id:"pron-ihr-nom-pl",category:"pronoun",de:"ihr",en:["you (informal, plural)"],hi:["तुम लोग"],hiTranslit:"tum log",ipa:"iːɐ̯",deva:"ईअ",level:"A1",illustration:"pron-ihr-nom-pl",type:"personal",person:2,number:"pl",formality:"informal",forms:{nom:"ihr",akk:"euch",dat:"euch",gen:"euer"},notes:'Addresses a group known informally; English "you" makes no singular/plural distinction here, but Hindi तुम लोग does.',examples:[{de:[{t:"Ihr",g:0},{t:"seid",g:1},{t:"meine Freunde",g:2}],en:[{t:"You all",g:0},{t:"are",g:1},{t:"my friends",g:2}],hi:[{t:"तुम लोग",g:0},{t:"मेरे दोस्त",g:2},{t:"हो",g:1}],hiTranslit:"tum log mere dost ho",note:'German distinguishes singular du from plural ihr for "you"; English collapses both into one word.'}]},{id:"pron-sie-pl",category:"pronoun",de:"sie",en:["they"],hi:["वे"],hiTranslit:"ve",ipa:"ziː",deva:"ज़ी",level:"A1",illustration:"pron-sie-pl",type:"personal",person:3,number:"pl",forms:{nom:"sie",akk:"sie",dat:"ihnen",gen:"ihrer"},notes:'Refers to any plural group regardless of gender — the same surface word that means "she" in the singular.',examples:[{de:[{t:"Sie",g:0},{t:"kommen",g:1},{t:"aus Frankreich",g:2}],en:[{t:"They",g:0},{t:"come",g:1},{t:"from France",g:2}],hi:[{t:"वे",g:0},{t:"फ़्रांस से",g:2},{t:"आते हैं",g:1}],hiTranslit:"ve France se aate hain",note:'Plural "sie" takes the -en verb ending, the same ending wir takes — Hindi marks each pronoun with its own distinct verb agreement.'}]},{id:"pron-sie-formal",category:"pronoun",de:"Sie",en:["you (formal)"],hi:["आप"],hiTranslit:"aap",ipa:"ziː",deva:"ज़ी",level:"A1",illustration:"pron-sie-formal",type:"personal",person:2,formality:"formal",forms:{nom:"Sie",akk:"Sie",dat:"Ihnen",gen:"Ihrer"},notes:'The polite "you," always capitalised, used with strangers and in professional settings — matched closely by Hindi आप, which English no longer distinguishes from informal "you".',examples:[{de:[{t:"Sie",g:0},{t:"sprechen",g:1},{t:"sehr gut",g:2},{t:"Deutsch",g:3}],en:[{t:"You",g:0},{t:"speak",g:1},{t:"German",g:3},{t:"very well",g:2}],hi:[{t:"आप",g:0},{t:"बहुत अच्छा",g:2},{t:"जर्मन",g:3},{t:"बोलते हैं",g:1}],hiTranslit:"aap bahut achha German bolte hain",note:'Formal "Sie" stays capitalised in every sentence position, not only at the start — a written cue absent from Hindi and English.'}]},{id:"pron-mich-akk",category:"pronoun",de:"mich",en:["me"],hi:["मुझे"],hiTranslit:"mujhe",ipa:"mɪç",deva:"मिख़्",level:"A1",illustration:"pron-mich-akk",type:"personal",person:1,number:"sg",forms:{nom:"ich",akk:"mich",dat:"mir",gen:"meiner"},notes:'The accusative of ich, used as a direct object — German case-marks the pronoun itself, exactly as Hindi मुझे does; English "me" only ever changes once, from "I".',examples:[{de:[{t:"Er",g:0},{t:"sieht",g:1},{t:"mich",g:2}],en:[{t:"He",g:0},{t:"sees",g:1},{t:"me",g:2}],hi:[{t:"वह",g:0},{t:"मुझे",g:2},{t:"देखता है",g:1}],hiTranslit:"vah mujhe dekhta hai",note:"The direct object mich sits right after the verb in German, but before the verb in Hindi."}]},{id:"pron-dich-akk",category:"pronoun",de:"dich",en:["you (informal, singular — object)"],hi:["तुम्हें"],hiTranslit:"tumhein",ipa:"dɪç",deva:"डिख़्",level:"A1",illustration:"pron-dich-akk",type:"personal",person:2,number:"sg",formality:"informal",forms:{nom:"du",akk:"dich",dat:"dir",gen:"deiner"},notes:'The accusative of du — used whenever informal "you" is the direct object of a verb.',examples:[{de:[{t:"Ich",g:0},{t:"sehe",g:1},{t:"dich",g:2}],en:[{t:"I",g:0},{t:"see",g:1},{t:"you",g:2}],hi:[{t:"मैं",g:0},{t:"तुम्हें",g:2},{t:"देखता हूँ",g:1}],hiTranslit:"main tumhein dekhta hoon",note:'German dich and Hindi तुम्हें both case-mark the object pronoun directly; English "you" stays unchanged from its subject form.'}]},{id:"pron-ihn",category:"pronoun",de:"ihn",en:["him","it (for a masculine noun)"],hi:["उसे"],hiTranslit:"use",ipa:"iːn",deva:"ईन्",level:"A1",illustration:"pron-ihn",type:"personal",person:3,number:"sg",gender:"m",forms:{nom:"er",akk:"ihn",dat:"ihm",gen:"seiner"},notes:"The accusative of er — replaces a masculine noun functioning as a direct object, e.g. den Film → ihn.",examples:[{de:[{t:"Ich",g:0},{t:"kaufe",g:1},{t:"ihn",g:2}],en:[{t:"I",g:0},{t:"buy",g:1},{t:"it",g:2}],hi:[{t:"मैं",g:0},{t:"उसे",g:2},{t:"खरीदता हूँ",g:1}],hiTranslit:"main use khareedta hoon",note:'Masculine accusative ihn has no separate English translation from neuter "it" — only German keeps the gender distinction alive here.'}]},{id:"pron-sie-akk-f",category:"pronoun",de:"sie",en:["her","it (for a feminine noun)"],hi:["उसे"],hiTranslit:"use",ipa:"ziː",deva:"ज़ी",level:"A1",illustration:"pron-sie-akk-f",type:"personal",person:3,number:"sg",gender:"f",forms:{nom:"sie",akk:"sie",dat:"ihr",gen:"ihrer"},notes:"The accusative of feminine sie is identical to its nominative form — only word order and context reveal its grammatical role.",examples:[{de:[{t:"Ich",g:0},{t:"kenne",g:1},{t:"sie",g:2},{t:"gut",g:3}],en:[{t:"I",g:0},{t:"know",g:1},{t:"her",g:2},{t:"well",g:3}],hi:[{t:"मैं",g:0},{t:"उसे",g:2},{t:"अच्छे से",g:3},{t:"जानता हूँ",g:1}],hiTranslit:"main use achhe se jaanta hoon",note:"German and English both place the manner adverb right after the object; Hindi places it just before the clause-final verb."}]},{id:"pron-uns-akk",category:"pronoun",de:"uns",en:["us"],hi:["हमें"],hiTranslit:"hamein",ipa:"ʊns",deva:"उन्स्",level:"A1",illustration:"pron-uns-akk",type:"personal",person:1,number:"pl",forms:{nom:"wir",akk:"uns",dat:"uns",gen:"unser"},notes:"The accusative (and dative) of wir — uns never changes shape between direct and indirect object, unlike ihn/ihm.",examples:[{de:[{t:"Sie",g:0},{t:"sieht",g:1},{t:"uns",g:2},{t:"heute",g:3}],en:[{t:"She",g:0},{t:"sees",g:1},{t:"us",g:2},{t:"today",g:3}],hi:[{t:"वह",g:0},{t:"आज",g:3},{t:"हमें",g:2},{t:"देखती है",g:1}],hiTranslit:"vah aaj hamein dekhti hai",note:"German and English keep the time adverb near the end of the clause; Hindi moves it forward, right after the subject."}]},{id:"pron-euch-akk",category:"pronoun",de:"euch",en:["you (informal, plural — object)"],hi:["तुम्हें"],hiTranslit:"tumhein",ipa:"ɔʏç",deva:"ऑयख़्",level:"A1",illustration:"pron-euch-akk",type:"personal",person:2,number:"pl",formality:"informal",forms:{nom:"ihr",akk:"euch",dat:"euch",gen:"euer"},notes:"The accusative (and dative) of ihr — one invariant form covers both direct and indirect object roles.",examples:[{de:[{t:"Ich",g:0},{t:"sehe",g:1},{t:"euch",g:2},{t:"morgen",g:3}],en:[{t:"I",g:0},{t:"will see",g:1},{t:"you all",g:2},{t:"tomorrow",g:3}],hi:[{t:"मैं",g:0},{t:"तुम्हें",g:2},{t:"कल",g:3},{t:"देखूँगा",g:1}],hiTranslit:"main tumhein kal dekhoonga",note:'German uses a plain present-tense verb with a future time word, where English marks the future on the verb itself with "will".'}]},{id:"pron-sie-akk-pl",category:"pronoun",de:"sie",en:["them"],hi:["उन्हें"],hiTranslit:"unhein",ipa:"ziː",deva:"ज़ी",level:"A1",illustration:"pron-sie-akk-pl",type:"personal",person:3,number:"pl",forms:{nom:"sie",akk:"sie",dat:"ihnen",gen:"ihrer"},notes:"Plural accusative sie is identical to plural nominative sie — case here is carried by the sentence, not the pronoun's shape.",examples:[{de:[{t:"Wir",g:0},{t:"treffen",g:1},{t:"sie",g:2},{t:"später",g:3}],en:[{t:"We",g:0},{t:"will meet",g:1},{t:"them",g:2},{t:"later",g:3}],hi:[{t:"हम",g:0},{t:"उन्हें",g:2},{t:"बाद में",g:3},{t:"मिलेंगे",g:1}],hiTranslit:"hum unhein baad mein milenge",note:"German lets a present-tense verb stand for the future given a time word; Hindi and English both shift the verb itself into future form."}]},{id:"pron-sie-akk-formal",category:"pronoun",de:"Sie",en:["you (formal — object)"],hi:["आपको"],hiTranslit:"aapko",ipa:"ziː",deva:"ज़ी",level:"A1",illustration:"pron-sie-akk-formal",type:"personal",person:2,formality:"formal",forms:{nom:"Sie",akk:"Sie",dat:"Ihnen",gen:"Ihrer"},notes:"The accusative of formal Sie is identical to its nominative — capitalisation is the only visual cue that this is the polite pronoun.",examples:[{de:[{t:"Ich",g:0},{t:"verstehe",g:1},{t:"Sie",g:2},{t:"gut",g:3}],en:[{t:"I",g:0},{t:"understand",g:1},{t:"you",g:2},{t:"well",g:3}],hi:[{t:"मैं",g:0},{t:"आपको",g:2},{t:"अच्छे से",g:3},{t:"समझता हूँ",g:1}],hiTranslit:"main aapko achhe se samajhta hoon",note:'Formal आपको and formal Sie both carry a politeness register that plain English "you" cannot show at all.'}]},{id:"pron-mir",category:"pronoun",de:"mir",en:["me (indirect object)","to me"],hi:["मुझे"],hiTranslit:"mujhe",ipa:"miːɐ̯",deva:"मीअ",level:"A1",illustration:"pron-mir",type:"personal",person:1,number:"sg",forms:{nom:"ich",akk:"mich",dat:"mir",gen:"meiner"},notes:`The dative of ich, marking an indirect object — German case-marks this on the pronoun itself, just as Hindi's मुझे does; English relies only on word order or "to me".`,examples:[{de:[{t:"Er",g:0},{t:"gibt",g:1},{t:"mir",g:2},{t:"das Buch",g:3}],en:[{t:"He",g:0},{t:"gives",g:1},{t:"me",g:2},{t:"the book",g:3}],hi:[{t:"वह",g:0},{t:"मुझे",g:2},{t:"किताब",g:3},{t:"देता है",g:1}],hiTranslit:"vah mujhe kitaab deta hai",note:'German and Hindi both place the indirect object before the direct object; English can do the same without "to".'}]},{id:"pron-dir",category:"pronoun",de:"dir",en:["you (informal — indirect object)","to you"],hi:["तुम्हें"],hiTranslit:"tumhein",ipa:"diːɐ̯",deva:"डीअ",level:"A1",illustration:"pron-dir",type:"personal",person:2,number:"sg",formality:"informal",forms:{nom:"du",akk:"dich",dat:"dir",gen:"deiner"},notes:"The dative of du — used for an informal indirect object; the identical Hindi तुम्हें serves both accusative and dative roles.",examples:[{de:[{t:"Ich",g:0},{t:"schenke",g:1},{t:"dir",g:2},{t:"eine Uhr",g:3}],en:[{t:"I",g:0},{t:"give",g:1},{t:"you",g:2},{t:"a watch",g:3}],hi:[{t:"मैं",g:0},{t:"तुम्हें",g:2},{t:"एक घड़ी",g:3},{t:"देता हूँ",g:1}],hiTranslit:"main tumhein ek ghadi deta hoon",note:"All three languages place the indirect object before the direct object in this double-object construction."}]},{id:"pron-ihm-dat-m",category:"pronoun",de:"ihm",en:["him (indirect object)","to him"],hi:["उसे"],hiTranslit:"use",ipa:"iːm",deva:"ईम्",level:"A1",illustration:"pron-ihm-dat-m",type:"personal",person:3,number:"sg",gender:"m",forms:{nom:"er",akk:"ihn",dat:"ihm",gen:"seiner"},notes:"The dative of masculine er — marks the indirect object, e.g. dem Mann → ihm.",examples:[{de:[{t:"Sie",g:0},{t:"antwortet",g:1},{t:"ihm",g:2},{t:"sofort",g:3}],en:[{t:"She",g:0},{t:"answers",g:1},{t:"him",g:2},{t:"immediately",g:3}],hi:[{t:"वह",g:0},{t:"उसे",g:2},{t:"फ़ौरन",g:3},{t:"जवाब देती है",g:1}],hiTranslit:"vah use fauran jawaab deti hai",note:"German ihn and ihm are distinct forms for masculine accusative and dative; Hindi उसे covers both cases identically."}]},{id:"pron-ihr-dat-f",category:"pronoun",de:"ihr",en:["her (indirect object)","to her"],hi:["उसे"],hiTranslit:"use",ipa:"iːɐ̯",deva:"ईअ",level:"A1",illustration:"pron-ihr-dat-f",type:"personal",person:3,number:"sg",gender:"f",forms:{nom:"sie",akk:"sie",dat:"ihr",gen:"ihrer"},notes:"The dative of feminine sie — distinct from its identical nominative/accusative form sie.",examples:[{de:[{t:"Ich",g:0},{t:"schreibe",g:1},{t:"ihr",g:2},{t:"einen Brief",g:3}],en:[{t:"I",g:0},{t:"write",g:1},{t:"her",g:2},{t:"a letter",g:3}],hi:[{t:"मैं",g:0},{t:"उसे",g:2},{t:"एक पत्र",g:3},{t:"लिखता हूँ",g:1}],hiTranslit:"main use ek patra likhta hoon",note:'German dative ihr and Hindi उसे both mark "her" as the indirect object; English "her" is identical to the accusative form.'}]},{id:"pron-ihm-dat-n",category:"pronoun",de:"ihm",en:["it (indirect object)","to it"],hi:["उसे"],hiTranslit:"use",ipa:"iːm",deva:"ईम्",level:"A1",illustration:"pron-ihm-dat-n",type:"personal",person:3,number:"sg",gender:"n",forms:{nom:"es",akk:"es",dat:"ihm",gen:"seiner"},notes:"The dative of neuter es — identical in form to the masculine dative ihm; gender is disambiguated only by context.",examples:[{de:[{t:"Wir",g:0},{t:"geben",g:1},{t:"ihm",g:2},{t:"Wasser",g:3}],en:[{t:"We",g:0},{t:"give",g:1},{t:"it",g:2},{t:"water",g:3}],hi:[{t:"हम",g:0},{t:"उसे",g:2},{t:"पानी",g:3},{t:"देते हैं",g:1}],hiTranslit:"hum use paani dete hain",note:"Neuter dative ihm and masculine dative ihm are spelled identically in German — only the noun each replaces reveals the gender."}]},{id:"pron-uns-dat",category:"pronoun",de:"uns",en:["us (indirect object)","to us"],hi:["हमें"],hiTranslit:"hamein",ipa:"ʊns",deva:"उन्स्",level:"A1",illustration:"pron-uns-dat",type:"personal",person:1,number:"pl",forms:{nom:"wir",akk:"uns",dat:"uns",gen:"unser"},notes:"The dative of wir, spelled identically to its accusative — one shape serves both grammatical roles.",examples:[{de:[{t:"Der Kellner",g:0},{t:"bringt",g:1},{t:"uns",g:2},{t:"die Speisekarte",g:3}],en:[{t:"The waiter",g:0},{t:"brings",g:1},{t:"us",g:2},{t:"the menu",g:3}],hi:[{t:"वेटर",g:0},{t:"हमें",g:2},{t:"मेन्यू",g:3},{t:"लाता है",g:1}],hiTranslit:"waiter hamein menu laata hai",note:"All three languages agree on subject-indirect-object-direct-object order here, an unusually close three-way match."}]},{id:"pron-euch-dat",category:"pronoun",de:"euch",en:["you all (indirect object)","to you all"],hi:["तुम्हें"],hiTranslit:"tumhein",ipa:"ɔʏç",deva:"ऑयख़्",level:"A1",illustration:"pron-euch-dat",type:"personal",person:2,number:"pl",formality:"informal",forms:{nom:"ihr",akk:"euch",dat:"euch",gen:"euer"},notes:"The dative of ihr, identical to its accusative euch — like uns, one form covers both object roles.",examples:[{de:[{t:"Die Lehrerin",g:0},{t:"zeigt",g:1},{t:"euch",g:2},{t:"die Antwort",g:3}],en:[{t:"The teacher",g:0},{t:"shows",g:1},{t:"you all",g:2},{t:"the answer",g:3}],hi:[{t:"शिक्षिका",g:0},{t:"तुम्हें",g:2},{t:"जवाब",g:3},{t:"दिखाती है",g:1}],hiTranslit:"shikshika tumhein jawaab dikhaati hai",note:"German keeps the verb second even with two objects following it; Hindi still saves the verb for the very end of the clause."}]},{id:"pron-ihnen",category:"pronoun",de:"ihnen",en:["them (indirect object)","to them"],hi:["उन्हें"],hiTranslit:"unhein",ipa:"ˈiːnən",deva:"ईनेन्",level:"A1",illustration:"pron-ihnen",type:"personal",person:3,number:"pl",forms:{nom:"sie",akk:"sie",dat:"ihnen",gen:"ihrer"},notes:"The dative of plural sie — a distinct form, unlike the nominative and accusative, which share one shape.",examples:[{de:[{t:"Wir",g:0},{t:"schicken",g:1},{t:"ihnen",g:2},{t:"die Einladung",g:3}],en:[{t:"We",g:0},{t:"send",g:1},{t:"them",g:2},{t:"the invitation",g:3}],hi:[{t:"हम",g:0},{t:"उन्हें",g:2},{t:"निमंत्रण",g:3},{t:"भेजते हैं",g:1}],hiTranslit:"hum unhein nimantran bhejte hain",note:"Dative ihnen is one of the few personal-pronoun forms with no overlap at all with its own nominative or accusative."}]},{id:"pron-ihnen-formal",category:"pronoun",de:"Ihnen",en:["you (formal — indirect object)","to you (formal)"],hi:["आपको"],hiTranslit:"aapko",ipa:"ˈiːnən",deva:"ईनेन्",level:"A1",illustration:"pron-ihnen-formal",type:"personal",person:2,formality:"formal",forms:{nom:"Sie",akk:"Sie",dat:"Ihnen",gen:"Ihrer"},notes:"The dative of formal Sie — capitalised like every form of the polite pronoun, and pronounced identically to plural ihnen.",examples:[{de:[{t:"Der Arzt",g:0},{t:"erklärt",g:1},{t:"Ihnen",g:2},{t:"die Diagnose",g:3}],en:[{t:"The doctor",g:0},{t:"explains",g:1},{t:"the diagnosis",g:3},{t:"to you",g:2}],hi:[{t:"डॉक्टर",g:0},{t:"आपको",g:2},{t:"निदान",g:3},{t:"समझाते हैं",g:1}],hiTranslit:"doctor aapko nidaan samjhaate hain",note:'German and Hindi place the indirect object before the direct object by default; English needs "to" to do the same job after the direct object.'}]},{id:"pron-mein",category:"pronoun",de:"mein",en:["my"],hi:["मेरा","मेरी","मेरे"],hiTranslit:"mera / meri / mere",ipa:"maɪn",deva:"माइन्",level:"A1",illustration:"pron-mein",type:"possessive",person:1,number:"sg",notes:`A possessive's ending agrees with the noun it possesses, not with the owner — mein Vater but meine Mutter. Hindi mirrors this exactly (मेरा पिता / मेरी माँ); English "my" never changes at all.`,examples:[{de:[{t:"Mein Vater",g:0},{t:"kocht gern",g:1}],en:[{t:"My father",g:0},{t:"likes to cook",g:1}],hi:[{t:"मेरा पिता",g:0},{t:"खाना बनाना पसंद करता है",g:1}],hiTranslit:"mera pita khaana banaana pasand karta hai",note:'German mein and Hindi मेरा both take their masculine form because Vater/पिता is masculine — English "my" would look identical either way.'}]},{id:"pron-dein",category:"pronoun",de:"dein",en:["your (informal)"],hi:["तुम्हारा","तुम्हारी","तुम्हारे"],hiTranslit:"tumhaara / tumhaari / tumhaare",ipa:"daɪn",deva:"डाइन्",level:"A1",illustration:"pron-dein",type:"possessive",person:2,formality:"informal",notes:`Like every German possessive, dein's ending tracks the possessed noun's gender, not the owner — dein Bruder but deine Schwester. Hindi तुम्हारा/तुम्हारी/तुम्हारे agrees the same way; English "your" stays fixed regardless.`,examples:[{de:[{t:"Ist",g:1},{t:"das",g:0},{t:"dein Auto",g:2}],en:[{t:"Is",g:1},{t:"that",g:0},{t:"your car",g:2}],hi:[{t:"क्या"},{t:"यह",g:0},{t:"तुम्हारी गाड़ी",g:2},{t:"है",g:1}],hiTranslit:"kya yah tumhaari gaadi hai",note:"German dein takes no extra ending before neuter Auto, while Hindi तुम्हारी agrees with गाड़ी's feminine gender — each language's agreement is internally consistent, but the genders themselves need not match across languages."}]},{id:"pron-sein",category:"pronoun",de:"sein",en:["his","its (masculine or neuter owner)"],hi:["उसका","उसकी","उसके"],hiTranslit:"uska / uski / uske",ipa:"zaɪn",deva:"ज़ाइन्",level:"A1",illustration:"pron-sein",type:"possessive",person:3,number:"sg",notes:`sein marks a masculine or neuter owner ("his"/"its"); like every German possessive, its ending agrees with the possessed noun, not the owner — seine Tasche is correct even though the owner is male, because Tasche is feminine. Hindi's उसका/उसकी/उसके works the same way; English "his" never changes.`,examples:[{de:[{t:"Er",g:0},{t:"sucht",g:1},{t:"seine Tasche",g:2}],en:[{t:"He",g:0},{t:"is looking for",g:1},{t:"his bag",g:2}],hi:[{t:"वह",g:0},{t:"अपना बैग",g:2},{t:"ढूंढ रहा है",g:1}],hiTranslit:"vah apna bag dhoondh raha hai",note:`German sein does not distinguish "his own" from "someone else's" — Hindi resolves that obligatorily with reflexive अपना versus non-reflexive उसका, a distinction English "his" also lacks.`}]},{id:"pron-ihr-poss-f",category:"pronoun",de:"ihr",en:["her"],hi:["उसका","उसकी","उसके"],hiTranslit:"uska / uski / uske",ipa:"iːɐ̯",deva:"ईअ",level:"A1",illustration:"pron-ihr-poss-f",type:"possessive",person:3,number:"sg",gender:"f",notes:`ihr marks a female owner ("her"); as with every German possessive, the ending agrees with the possessed noun, not the owner — ihr Mann takes no extra ending because Mann is masculine, while ihre Tasche does because Tasche is feminine. Hindi's उसका/उसकी/उसके tracks the same noun-gender agreement; English "her" never changes.`,examples:[{de:[{t:"Ihr Mann",g:0},{t:"arbeitet",g:1},{t:"viel",g:2}],en:[{t:"Her husband",g:0},{t:"works",g:1},{t:"a lot",g:2}],hi:[{t:"उसका पति",g:0},{t:"बहुत",g:2},{t:"काम करता है",g:1}],hiTranslit:"uska pati bahut kaam karta hai",note:"Ihr Mann takes no extra ending because Mann is masculine — the same possessive becomes ihre before a feminine noun like Frau."}]},{id:"pron-unser",category:"pronoun",de:"unser",en:["our"],hi:["हमारा","हमारी","हमारे"],hiTranslit:"hamaara / hamaari / hamaare",ipa:"ˈʊnzɐ",deva:"उन्ज़ा",level:"A1",illustration:"pron-unser",type:"possessive",person:1,number:"pl",notes:'unser follows the same rule as every German possessive: its ending agrees with the possessed noun, not with the plural owners — unser Haus but unsere Wohnung. Hindi हमारा/हमारी/हमारे works identically; English "our" is invariant.',examples:[{de:[{t:"Unser Haus",g:0},{t:"ist",g:1},{t:"alt",g:2}],en:[{t:"Our house",g:0},{t:"is",g:1},{t:"old",g:2}],hi:[{t:"हमारा घर",g:0},{t:"पुराना",g:2},{t:"है",g:1}],hiTranslit:"hamaara ghar puraana hai",note:'German and Hindi both place the descriptive adjective right before the verb it modifies; English puts it right after "is" instead.'}]},{id:"pron-euer",category:"pronoun",de:"euer",en:["your (informal, plural)"],hi:["तुम्हारा","तुम्हारी","तुम्हारे"],hiTranslit:"tumhaara / tumhaari / tumhaare",ipa:"ˈɔʏɐ",deva:"ऑया",level:"A1",illustration:"pron-euer",type:"possessive",person:2,number:"pl",formality:"informal",notes:`euer follows the same possessive-agreement rule as the rest: euer Lehrer but eure Schule — the ending tracks the possessed noun's gender, not the group of owners. Hindi तुम्हारा/तुम्हारी/तुम्हारे agrees the same way; English "your" never changes at all.`,examples:[{de:[{t:"Ist",g:1},{t:"das",g:0},{t:"euer Hund",g:2}],en:[{t:"Is",g:1},{t:"that",g:0},{t:"your dog",g:2}],hi:[{t:"क्या"},{t:"यह",g:0},{t:"तुम्हारा कुत्ता",g:2},{t:"है",g:1}],hiTranslit:"kya yah tumhaara kutta hai",note:"Hund and कुत्ता are both grammatically masculine, so euer and तुम्हारा happen to take the same bare masculine form here."}]},{id:"pron-ihr-poss-pl",category:"pronoun",de:"ihr",en:["their"],hi:["उनका","उनकी","उनके"],hiTranslit:"unka / unki / unke",ipa:"iːɐ̯",deva:"ईअ",level:"A1",illustration:"pron-ihr-poss-pl",type:"possessive",person:3,number:"pl",notes:'This ihr means "their" (plural owners) — not to be confused with ihr meaning "her" or ihr meaning "you all". Like every German possessive, its ending agrees with the possessed noun: ihr Auto but ihre Kinder. Hindi उनका/उनकी/उनके follows the identical rule; English "their" is invariant.',examples:[{de:[{t:"Ihre Kinder",g:0},{t:"spielen",g:1},{t:"im Garten",g:2}],en:[{t:"Their children",g:0},{t:"play",g:1},{t:"in the garden",g:2}],hi:[{t:"उनके बच्चे",g:0},{t:"बगीचे में",g:2},{t:"खेलते हैं",g:1}],hiTranslit:"unke bachche bageeche mein khelte hain",note:"Plural Kinder takes ihre and plural बच्चे takes उनके — both possessives agree with a plural possessed noun, each in its own language's way."}]},{id:"pron-ihr-poss-formal",category:"pronoun",de:"Ihr",en:["your (formal)"],hi:["आपका","आपकी","आपके"],hiTranslit:"aapka / aapki / aapke",ipa:"iːɐ̯",deva:"ईअ",level:"A1",illustration:"pron-ihr-poss-formal",type:"possessive",person:2,formality:"formal",notes:'The formal possessive, always capitalised like its pronoun Sie. As with every German possessive, its ending agrees with the possessed noun — Ihr Name but Ihre Adresse. Hindi आपका/आपकी/आपके mirrors this agreement; English "your" stays the same either way.',examples:[{de:[{t:"Wie",g:2},{t:"ist",g:1},{t:"Ihr Name",g:0}],en:[{t:"What",g:2},{t:"is",g:1},{t:"your name",g:0}],hi:[{t:"आपका नाम",g:0},{t:"क्या",g:2},{t:"है",g:1}],hiTranslit:"aapka naam kya hai",note:"German and English front the question word wie/what; Hindi keeps its question word क्या in place, right before the verb."}]},{id:"pron-mich-refl",category:"pronoun",de:"mich",en:["myself"],hi:["खुद को"],hiTranslit:"khud ko",ipa:"mɪç",deva:"मिख़्",level:"A2",illustration:"pron-mich-refl",type:"reflexive",person:1,number:"sg",forms:{akk:"mich",dat:"mir"},notes:"Reflexive mich has the same shape as accusative mich — German reuses the ordinary object pronoun rather than a dedicated reflexive form, except in the 3rd person (sich).",examples:[{de:[{t:"Ich",g:0},{t:"wasche",g:1},{t:"mich",g:2},{t:"jeden Morgen",g:3}],en:[{t:"I",g:0},{t:"wash",g:1},{t:"myself",g:2},{t:"every morning",g:3}],hi:[{t:"मैं",g:0},{t:"हर सुबह",g:3},{t:"खुद को",g:2},{t:"धोता हूँ",g:1}],hiTranslit:"main har subah khud ko dhota hoon",note:"German and English both place the time phrase after the reflexive object; Hindi places it before, right after the subject."}]},{id:"pron-dich-refl",category:"pronoun",de:"dich",en:["yourself (informal)"],hi:["खुद को"],hiTranslit:"khud ko",ipa:"dɪç",deva:"डिख़्",level:"A2",illustration:"pron-dich-refl",type:"reflexive",person:2,number:"sg",formality:"informal",forms:{akk:"dich",dat:"dir"},notes:"Reflexive dich reuses the ordinary accusative form of du — like mich, it is not a separate dedicated reflexive word.",examples:[{de:[{t:"Du",g:0},{t:"verletzt",g:1},{t:"dich",g:2},{t:"beim Sport",g:3}],en:[{t:"You",g:0},{t:"hurt",g:1},{t:"yourself",g:2},{t:"during sports",g:3}],hi:[{t:"तुम",g:0},{t:"खेल के दौरान",g:3},{t:"खुद को",g:2},{t:"चोट पहुँचाते हो",g:1}],hiTranslit:"tum khel ke dauraan khud ko chot pahunchaate ho",note:'The reflexive object dich must appear even where casual English drops "yourself" ("you hurt easily") — German never allows that omission.'}]},{id:"pron-sich",category:"pronoun",de:"sich",en:["himself","herself","itself","themselves","yourself (formal)"],hi:["खुद को","अपने आप को"],hiTranslit:"khud ko / apne aap ko",ipa:"zɪç",deva:"ज़िख़्",level:"A2",illustration:"pron-sich",type:"reflexive",person:3,forms:{akk:"sich",dat:"sich"},notes:"The one true dedicated reflexive pronoun in German — invariant across gender, number, and even the formal Sie, unlike mich/dich/uns/euch which just reuse ordinary object forms.",examples:[{de:[{t:"Sie",g:0},{t:"kämmt",g:1},{t:"sich",g:2},{t:"die Haare",g:3}],en:[{t:"She",g:0},{t:"combs",g:1},{t:"her",g:2},{t:"hair",g:3}],hi:[{t:"वह",g:0},{t:"अपने",g:2},{t:"बाल",g:3},{t:"संवारती है",g:1}],hiTranslit:"vah apne baal sanvaarti hai",note:'German marks the possessor of "hair" with a separate dative reflexive sich; Hindi folds that meaning into the possessive अपने, and English into "her".'}]},{id:"pron-uns-refl",category:"pronoun",de:"uns",en:["ourselves"],hi:["खुद को"],hiTranslit:"khud ko",ipa:"ʊns",deva:"उन्स्",level:"A2",illustration:"pron-uns-refl",type:"reflexive",person:1,number:"pl",forms:{akk:"uns",dat:"uns"},notes:"Reflexive uns is identical to the ordinary accusative/dative uns — 1st- and 2nd-person pronouns never get a special reflexive shape.",examples:[{de:[{t:"Wir",g:0},{t:"freuen",g:1},{t:"uns"},{t:"auf die Ferien",g:2}],en:[{t:"We",g:0},{t:"are looking forward",g:1},{t:"to the holidays",g:2}],hi:[{t:"हम",g:0},{t:"छुट्टियों का",g:2},{t:"इंतज़ार कर रहे हैं",g:1}],hiTranslit:"hum chhuttiyon ka intezaar kar rahe hain",note:`German's reflexive verb sich freuen requires uns even though nothing is done "to oneself"; neither Hindi nor English needs any reflexive marker here.`}]},{id:"pron-euch-refl",category:"pronoun",de:"euch",en:["yourselves"],hi:["खुद को"],hiTranslit:"khud ko",ipa:"ɔʏç",deva:"ऑयख़्",level:"A2",illustration:"pron-euch-refl",type:"reflexive",person:2,number:"pl",formality:"informal",forms:{akk:"euch",dat:"euch"},notes:"Reflexive euch reuses the ordinary accusative/dative euch — like uns, this pronoun has no separate reflexive form.",examples:[{de:[{t:"Ihr",g:0},{t:"müsst",g:1},{t:"euch"},{t:"entscheiden",g:2}],en:[{t:"You all",g:0},{t:"must",g:1},{t:"decide",g:2}],hi:[{t:"तुम्हें",g:0},{t:"फ़ैसला करना",g:2},{t:"होगा",g:1}],hiTranslit:"tumhein faisla karna hoga",note:"German's reflexive verb sich entscheiden requires euch with no real reflexive meaning; Hindi's obligation construction needs no reflexive pronoun at all."}]},{id:"pron-dieser",category:"pronoun",de:"dieser",en:["this (masculine, nominative)"],hi:["यह"],hiTranslit:"yah",ipa:"ˈdiːzɐ",deva:"डीज़ा",level:"A1",illustration:"pron-dieser",type:"demonstrative",gender:"m",number:"sg",notes:`dieser changes shape with the noun's gender and case (dieser/diese/dieses/diesen…); both Hindi यह and English "this" stay fixed regardless.`,examples:[{de:[{t:"Dieser Mann",g:0},{t:"ist",g:1},{t:"mein Nachbar",g:2}],en:[{t:"This man",g:0},{t:"is",g:1},{t:"my neighbour",g:2}],hi:[{t:"यह आदमी",g:0},{t:"मेरा पड़ोसी",g:2},{t:"है",g:1}],hiTranslit:"yah aadmi mera padosi hai",note:'German dieser is masculine nominative here because Mann is masculine; Hindi यह and English "this" would look identical for any gender.'}]},{id:"pron-diese",category:"pronoun",de:"diese",en:["this (feminine)","these (plural)"],hi:["यह","ये"],hiTranslit:"yah / ye",ipa:"ˈdiːzə",deva:"डीज़े",level:"A1",illustration:"pron-diese",type:"demonstrative",gender:"f",number:"sg",notes:'diese is the feminine singular form of dieser, and — confusingly for learners — also the form used for all-gender plural ("these"); Hindi keeps singular यह separate from plural ये, which German diese does not.',examples:[{de:[{t:"Diese Frau",g:0},{t:"kommt",g:1},{t:"aus Spanien",g:2}],en:[{t:"This woman",g:0},{t:"comes",g:1},{t:"from Spain",g:2}],hi:[{t:"यह औरत",g:0},{t:"स्पेन से",g:2},{t:"आती है",g:1}],hiTranslit:"yah aurat Spain se aati hai",note:`diese here is feminine singular ("this"); the identical spelling also serves as the plural ("these") — a syncretism absent from Hindi's यह/ये distinction.`}]},{id:"pron-dieses",category:"pronoun",de:"dieses",en:["this (neuter)"],hi:["यह"],hiTranslit:"yah",ipa:"ˈdiːzəs",deva:"डीज़ेस्",level:"A1",illustration:"pron-dieses",type:"demonstrative",gender:"n",number:"sg",notes:'dieses is the neuter form, used before neuter nouns like das Jahr or das Kind; both Hindi यह and English "this" stay the same regardless of gender.',examples:[{de:[{t:"Dieses Jahr",g:0},{t:"ist",g:1},{t:"besonders",g:2}],en:[{t:"This year",g:0},{t:"is",g:1},{t:"special",g:2}],hi:[{t:"यह साल",g:0},{t:"खास",g:2},{t:"है",g:1}],hiTranslit:"yah saal khaas hai",note:`Neuter dieses marks Jahr's gender directly on the demonstrative; Hindi यह and English "this" carry no gender information at all.`}]},{id:"pron-jener",category:"pronoun",de:"jener",en:["that (masculine, nominative)"],hi:["वह"],hiTranslit:"vah",ipa:"ˈjeːnɐ",deva:"येना",level:"A2",illustration:"pron-jener",type:"demonstrative",gender:"m",number:"sg",notes:'jener marks something more distant than dieser and is rare in speech — most spoken German prefers der/die/das with stress, reserving jener mainly for written contrast with dieser ("the former... the latter...").',examples:[{de:[{t:"Jener Tag",g:0},{t:"bleibt",g:1},{t:"unvergessen",g:2}],en:[{t:"That day",g:0},{t:"remains",g:1},{t:"unforgettable",g:2}],hi:[{t:"वह दिन",g:0},{t:"अविस्मरणीय",g:2},{t:"रहता है",g:1}],hiTranslit:"vah din avismarniya rehta hai",note:`Literary jener corresponds to Hindi's ordinary distal वह — German reserves a special word for "that" where Hindi and English use their everyday demonstrative.`}]},{id:"pron-jene",category:"pronoun",de:"jene",en:["that (feminine)","those (plural)"],hi:["वह","वे"],hiTranslit:"vah / ve",ipa:"ˈjeːnə",deva:"येने",level:"A2",illustration:"pron-jene",type:"demonstrative",gender:"f",number:"sg",notes:"jene is the feminine singular (and plural) form of jener, patterning exactly like dieser/diese — the same -e ending marks both feminine singular and all-gender plural.",examples:[{de:[{t:"Jene Frau",g:0},{t:"war",g:1},{t:"meine Lehrerin",g:2}],en:[{t:"That woman",g:0},{t:"was",g:1},{t:"my teacher",g:2}],hi:[{t:"वह औरत",g:0},{t:"मेरी शिक्षिका",g:2},{t:"थी",g:1}],hiTranslit:"vah aurat meri shikshika thi",note:'Past-tense war and थी both agree with their feminine subject in gender, while English "was" carries no gender marking at all.'}]},{id:"pron-jenes",category:"pronoun",de:"jenes",en:["that (neuter)"],hi:["वह"],hiTranslit:"vah",ipa:"ˈjeːnəs",deva:"येनेस्",level:"A2",illustration:"pron-jenes",type:"demonstrative",gender:"n",number:"sg",notes:'jenes is the neuter counterpart of jener/jene, used before neuter nouns like das Haus; again, Hindi वह and English "that" show no gender at all.',examples:[{de:[{t:"Jenes Haus",g:0},{t:"gehört",g:1},{t:"meinem Onkel",g:2}],en:[{t:"That house",g:0},{t:"belongs to",g:1},{t:"my uncle",g:2}],hi:[{t:"वह घर",g:0},{t:"मेरे चाचा का",g:2},{t:"है",g:1}],hiTranslit:"vah ghar mere chacha ka hai",note:'German marks "belongs to" with a dative object; Hindi instead uses a genitive construction meaning literally "of my uncle" — two different case strategies for the same relation.'}]},{id:"pron-derselbe",category:"pronoun",de:"derselbe",en:["the same (masculine, nominative)"],hi:["वही"],hiTranslit:"vahi",ipa:"deːɐ̯ˈzɛlbə",deva:"डेअज़ेल्बे",level:"B1",illustration:"pron-derselbe",type:"demonstrative",gender:"m",number:"sg",notes:'derselbe is written as one word but declines in two places at once — both der and selbe change (denselben, derselben…) — while Hindi वही is a single invariant word built from वह + ही ("that + very").',examples:[{de:[{t:"Derselbe Mann",g:0},{t:"war",g:1},{t:"gestern",g:2},{t:"hier",g:3}],en:[{t:"The same man",g:0},{t:"was",g:1},{t:"here",g:3},{t:"yesterday",g:2}],hi:[{t:"वही आदमी",g:0},{t:"कल",g:2},{t:"यहाँ",g:3},{t:"था",g:1}],hiTranslit:"vahi aadmi kal yahaan tha",note:'German and Hindi both place the time word before the place word; English reverses that order, putting "here" before "yesterday".'}]},{id:"pron-solcher",category:"pronoun",de:"solcher",en:["such a (masculine, nominative)"],hi:["ऐसा"],hiTranslit:"aisa",ipa:"ˈzɔlçɐ",deva:"ज़ॉल्ख़ा",level:"B1",illustration:"pron-solcher",type:"demonstrative",gender:"m",number:"sg",notes:"solcher is formal and literary; everyday spoken German almost always prefers so ein Mann instead of solch ein/solcher Mann.",examples:[{de:[{t:"Solcher Mut",g:0},{t:"ist",g:1},{t:"selten",g:2}],en:[{t:"Such courage",g:0},{t:"is",g:1},{t:"rare",g:2}],hi:[{t:"ऐसा साहस",g:0},{t:"दुर्लभ",g:2},{t:"है",g:1}],hiTranslit:"aisa saahas durlabh hai",note:'Formal solcher needs no article at all before the noun, just like Hindi ऐसा — English "such" instead requires the indefinite article "a" in the singular.'}]},{id:"pron-das-dem",category:"pronoun",de:"das",en:["this","that"],hi:["यह"],hiTranslit:"yah",ipa:"das",deva:"डस्",level:"A1",illustration:"pron-das-dem",type:"demonstrative",number:"sg",notes:"Used alone, not before a noun, das points at something in general — an idea, situation, or unnamed object — rather than agreeing with any specific noun's gender.",examples:[{de:[{t:"Das",g:0},{t:"ist",g:1},{t:"mein Lieblingsbuch",g:2}],en:[{t:"This",g:0},{t:"is",g:1},{t:"my favourite book",g:2}],hi:[{t:"यह",g:0},{t:"मेरी पसंदीदा किताब",g:2},{t:"है",g:1}],hiTranslit:"yah meri pasandeeda kitaab hai",note:"Free-standing das works the same way whether it introduces a masculine, feminine, or neuter noun — this das itself never changes for gender."}]},{id:"pron-der-rel",category:"pronoun",de:"der",en:["who","that (masculine subject)"],hi:["जो"],hiTranslit:"jo",ipa:"deːɐ̯",deva:"डेअ",level:"B1",illustration:"pron-der-rel",type:"relative",gender:"m",forms:{nom:"der",akk:"den",dat:"dem",gen:"dessen"},notes:"Introduces a relative clause about a masculine antecedent and sends the verb to the clause's end — Hindi जो does the same job but carries no gender marking at all.",examples:[{de:[{t:"Der Mann,",g:0},{t:"der",g:1},{t:"dort steht,",g:2},{t:"ist",g:3},{t:"mein Onkel",g:4}],en:[{t:"The man",g:0},{t:"who",g:1},{t:"is standing there",g:2},{t:"is",g:3},{t:"my uncle",g:4}],hi:[{t:"जो",g:1},{t:"आदमी",g:0},{t:"वहाँ खड़ा है,",g:2},{t:"वह"},{t:"मेरा चाचा",g:4},{t:"है",g:3}],hiTranslit:"jo aadmi vahaan khada hai, vah mera chacha hai",note:`Hindi uses a correlative जो...वह pair — a resumptive वह ("he") that German and English simply don't need with their single relative pronoun der/who.`}]},{id:"pron-die-rel",category:"pronoun",de:"die",en:["who","that (feminine or plural subject)"],hi:["जो"],hiTranslit:"jo",ipa:"diː",deva:"डी",level:"B1",illustration:"pron-die-rel",type:"relative",gender:"f",forms:{nom:"die",akk:"die",dat:"der",gen:"deren"},notes:"die introduces a relative clause about a feminine or plural antecedent; Hindi जो is identical for every gender and number.",examples:[{de:[{t:"Die Frau,",g:0},{t:"die",g:1},{t:"dort steht,",g:2},{t:"ist",g:3},{t:"meine Tante",g:4}],en:[{t:"The woman",g:0},{t:"who",g:1},{t:"is standing there",g:2},{t:"is",g:3},{t:"my aunt",g:4}],hi:[{t:"जो",g:1},{t:"औरत",g:0},{t:"वहाँ खड़ी है,",g:2},{t:"वह"},{t:"मेरी चाची",g:4},{t:"है",g:3}],hiTranslit:"jo aurat vahaan khadi hai, vah meri chachi hai",note:`Relative die matches Frau's feminine gender in German; Hindi जो and English "who" both stay the same for any gender.`}]},{id:"pron-das-rel",category:"pronoun",de:"das",en:["which","that (neuter subject)"],hi:["जो"],hiTranslit:"jo",ipa:"das",deva:"डस्",level:"B1",illustration:"pron-das-rel",type:"relative",gender:"n",forms:{nom:"das",akk:"das",dat:"dem",gen:"dessen"},notes:"das introduces a relative clause about a neuter antecedent; the identical spelling to the neuter article der/die/das is no coincidence — German relative pronouns are built on the definite article.",examples:[{de:[{t:"Das Auto,",g:0},{t:"das",g:1},{t:"dort steht,",g:2},{t:"gehört",g:3},{t:"mir",g:4}],en:[{t:"The car",g:0},{t:"that",g:1},{t:"is parked there",g:2},{t:"belongs to",g:3},{t:"me",g:4}],hi:[{t:"जो",g:1},{t:"गाड़ी",g:0},{t:"वहाँ खड़ी है,",g:2},{t:"वह"},{t:"मेरी",g:4},{t:"है",g:3}],hiTranslit:"jo gaadi vahaan khadi hai, vah meri hai",note:"German's relative das is spelled exactly like the neuter article das — a family resemblance Hindi's all-purpose जो shares with no article."}]},{id:"pron-welcher-rel",category:"pronoun",de:"welcher",en:["which (masculine, nominative — relative)"],hi:["जो"],hiTranslit:"jo",ipa:"ˈvɛlçɐ",deva:"वेल्ख़ा",level:"B1",illustration:"pron-welcher-rel",type:"relative",gender:"m",notes:"welcher is a more formal, less common alternative to der/die/das as a relative pronoun — mostly found in written German to avoid repeating der twice in one sentence.",examples:[{de:[{t:"Der Zug,",g:0},{t:"welcher",g:1},{t:"um acht abfährt,",g:2},{t:"ist",g:3},{t:"voll",g:4}],en:[{t:"The train",g:0},{t:"which",g:1},{t:"leaves at eight",g:2},{t:"is",g:3},{t:"full",g:4}],hi:[{t:"जो",g:1},{t:"ट्रेन",g:0},{t:"आठ बजे जाती है,",g:2},{t:"वह"},{t:"भरी",g:4},{t:"है",g:3}],hiTranslit:"jo train aath baje jaati hai, vah bhari hai",note:'welcher exists mainly to avoid saying "der Zug, der..." twice in writing; spoken German almost always uses der instead.'}]},{id:"pron-welche-rel",category:"pronoun",de:"welche",en:["which (feminine or plural — relative)"],hi:["जो"],hiTranslit:"jo",ipa:"ˈvɛlçə",deva:"वेल्ख़े",level:"B1",illustration:"pron-welche-rel",type:"relative",gender:"f",notes:"welche is the feminine/plural counterpart of welcher, following the same gender pattern as der-words; like welcher, it sounds more formal than simply reusing die.",examples:[{de:[{t:"Die Stadt,",g:0},{t:"welche",g:1},{t:"wir besuchten,",g:2},{t:"war",g:3},{t:"wunderschön",g:4}],en:[{t:"The city",g:0},{t:"which",g:1},{t:"we visited",g:2},{t:"was",g:3},{t:"beautiful",g:4}],hi:[{t:"जो",g:1},{t:"शहर",g:0},{t:"हमने देखा,",g:2},{t:"वह"},{t:"बहुत सुंदर",g:4},{t:"था",g:3}],hiTranslit:"jo shahar humne dekha, vah bahut sundar tha",note:"German fronts the relative clause right after its noun; Hindi's जो-clause instead comes first, with the main clause and its resumptive वह following."}]},{id:"pron-welches-rel",category:"pronoun",de:"welches",en:["which (neuter — relative)"],hi:["जो"],hiTranslit:"jo",ipa:"ˈvɛlçəs",deva:"वेल्ख़ेस्",level:"B1",illustration:"pron-welches-rel",type:"relative",gender:"n",notes:"welches is the neuter form, completing the der/die/das-based pattern welcher/welche/welches; everyday German usually prefers plain das instead.",examples:[{de:[{t:"Das Buch,",g:0},{t:"welches",g:1},{t:"ich lese,",g:2},{t:"ist",g:3},{t:"spannend",g:4}],en:[{t:"The book",g:0},{t:"which",g:1},{t:"I am reading",g:2},{t:"is",g:3},{t:"exciting",g:4}],hi:[{t:"जो",g:1},{t:"किताब",g:0},{t:"मैं पढ़ रहा हूँ,",g:2},{t:"वह"},{t:"रोमांचक",g:4},{t:"है",g:3}],hiTranslit:"jo kitaab main padh raha hoon, vah romaanchak hai",note:"welches, like welcher and welche, is built directly on the neuter article das plus a declension ending — the same der-word pattern that shapes every German relative pronoun."}]},{id:"pron-was-rel",category:"pronoun",de:"was",en:["which","that (relative, referring to a whole clause or indefinite)"],hi:["जो"],hiTranslit:"jo",ipa:"vas",deva:"वस्",level:"B1",illustration:"pron-was-rel",type:"relative",notes:"was as a relative pronoun refers back to indefinites (alles, etwas, nichts) or to an entire preceding clause, not to an ordinary noun — der/die/das cover those cases instead.",examples:[{de:[{t:"Er hat mir geholfen,",g:0},{t:"was",g:1},{t:"ich",g:2},{t:"nie",g:3},{t:"vergessen werde",g:4}],en:[{t:"He helped me,",g:0},{t:"which",g:1},{t:"I",g:2},{t:"will never",g:3},{t:"forget",g:4}],hi:[{t:"उसने मेरी मदद की,",g:0},{t:"जो",g:1},{t:"मैं",g:2},{t:"कभी नहीं",g:3},{t:"भूलूँगा",g:4}],hiTranslit:"usne meri madad ki, jo main kabhi nahin bhoolunga",note:'was here refers back to the entire preceding clause, not to a specific noun — exactly like English "which" and Hindi जो used the same way.'}]},{id:"pron-wer",category:"pronoun",de:"wer",en:["who"],hi:["कौन"],hiTranslit:"kaun",ipa:"veːɐ̯",deva:"वेअ",level:"A1",illustration:"pron-wer",type:"interrogative",forms:{nom:"wer",akk:"wen",dat:"wem",gen:"wessen"},notes:"wer asks about the identity of a person as the subject; German, Hindi, and English all place this question word prominently, though not always in the same position.",examples:[{de:[{t:"Wer",g:0},{t:"kommt",g:1},{t:"heute",g:2}],en:[{t:"Who",g:0},{t:"is coming",g:1},{t:"today",g:2}],hi:[{t:"आज",g:2},{t:"कौन",g:0},{t:"आ रहा है",g:1}],hiTranslit:"aaj kaun aa raha hai",note:"German and English front the question word wer/who; Hindi keeps कौन in normal subject position and puts the time word first instead."}]},{id:"pron-wen",category:"pronoun",de:"wen",en:["whom"],hi:["किसे"],hiTranslit:"kise",ipa:"veːn",deva:"वेन्",level:"A1",illustration:"pron-wen",type:"interrogative",forms:{nom:"wer",akk:"wen",dat:"wem",gen:"wessen"},notes:'wen is the accusative of wer, asking about a direct object — a distinction spoken English has largely dropped in favour of "who".',examples:[{de:[{t:"Wen",g:0},{t:"triffst du",g:1},{t:"morgen",g:2}],en:[{t:"Whom",g:0},{t:"are you meeting",g:1},{t:"tomorrow",g:2}],hi:[{t:"कल",g:2},{t:"किससे",g:0},{t:"मिलोगे",g:1}],hiTranslit:"kal kisse miloge",note:"German fronts accusative wen just like nominative wer; Hindi's किससे additionally carries the postposition से that the verb मिलना requires."}]},{id:"pron-wem",category:"pronoun",de:"wem",en:["(to) whom"],hi:["किसे"],hiTranslit:"kise",ipa:"veːm",deva:"वेम्",level:"A1",illustration:"pron-wem",type:"interrogative",forms:{nom:"wer",akk:"wen",dat:"wem",gen:"wessen"},notes:'wem is the dative of wer, asking about an indirect object — English typically no longer distinguishes this from plain "who" in speech.',examples:[{de:[{t:"Wem",g:0},{t:"gehört",g:1},{t:"dieses Buch",g:2}],en:[{t:"Whose",g:0},{t:"is",g:1},{t:"this book",g:2}],hi:[{t:"यह किताब",g:2},{t:"किसकी",g:0},{t:"है",g:1}],hiTranslit:"yah kitaab kiski hai",note:'German asks "to whom does this book belong" using dative wem; English and Hindi instead ask "whose," using a genitive/possessive question word for the identical meaning.'}]},{id:"pron-wessen",category:"pronoun",de:"wessen",en:["whose"],hi:["किसका","किसकी","किसके"],hiTranslit:"kiska / kiski / kiske",ipa:"ˈvɛsən",deva:"वेसेन्",level:"B1",illustration:"pron-wessen",type:"interrogative",forms:{nom:"wer",akk:"wen",dat:"wem",gen:"wessen"},notes:"wessen is the genitive of wer, asking about ownership; unlike German's own possessives mein/dein, wessen itself never changes for the possessed noun's gender — it precedes the noun unaltered.",examples:[{de:[{t:"Wessen Auto",g:0},{t:"ist",g:1},{t:"das",g:2}],en:[{t:"Whose car",g:0},{t:"is",g:1},{t:"that",g:2}],hi:[{t:"यह",g:2},{t:"किसकी गाड़ी",g:0},{t:"है",g:1}],hiTranslit:"yah kiski gaadi hai",note:"German wessen stays fixed regardless of the possessed noun's gender; Hindi किसका/किसकी/किसके instead agrees, closer to how German's own possessives mein/dein behave."}]},{id:"pron-was-interrog",category:"pronoun",de:"was",en:["what"],hi:["क्या"],hiTranslit:"kya",ipa:"vas",deva:"वस्",level:"A1",illustration:"pron-was-interrog",type:"interrogative",notes:"was asks about a thing rather than a person (contrast wer); it stays the same for nominative and accusative, unlike wer/wen.",examples:[{de:[{t:"Was",g:0},{t:"machst du",g:1},{t:"gerade",g:2}],en:[{t:"What",g:0},{t:"are you doing",g:1},{t:"right now",g:2}],hi:[{t:"अभी",g:2},{t:"क्या",g:0},{t:"कर रहे हो",g:1}],hiTranslit:"abhi kya kar rahe ho",note:"German and English front the question word was/what; Hindi keeps क्या in its ordinary object position, just before the verb."}]},{id:"pron-welcher-interrog",category:"pronoun",de:"welcher",en:["which (masculine, nominative — question word)"],hi:["कौन सा"],hiTranslit:"kaun sa",ipa:"ˈvɛlçɐ",deva:"वेल्ख़ा",level:"A2",illustration:"pron-welcher-interrog",type:"interrogative",gender:"m",notes:`As a question word, welcher/welche/welches asks for a specific choice among options and agrees with the noun's gender — Hindi कौन सा/कौन सी/कौन सा does the same, while English "which" never changes.`,examples:[{de:[{t:"Welcher Zug",g:0},{t:"fährt",g:1},{t:"nach Berlin",g:2}],en:[{t:"Which train",g:0},{t:"goes",g:1},{t:"to Berlin",g:2}],hi:[{t:"कौन सी ट्रेन",g:0},{t:"बर्लिन",g:2},{t:"जाती है",g:1}],hiTranslit:"kaun si train Berlin jaati hai",note:"welcher agrees with masculine Zug in German, while Hindi कौन सी agrees with feminine ट्रेन — the two languages assign grammatical gender independently of each other."}]},{id:"pron-man",category:"pronoun",de:"man",en:["one","you (generic)","people (in general)"],hi:["कोई","लोग"],hiTranslit:"koi / log",ipa:"man",deva:"मन्",level:"A1",illustration:"pron-man",type:"indefinite",notes:'man is a generic subject pronoun always used with a 3rd-person-singular verb — it has no accusative/dative form of its own; English "one" is similarly formal, but everyday English usually says generic "you" instead.',examples:[{de:[{t:"Man"},{t:"darf",g:0},{t:"hier",g:1},{t:"nicht rauchen",g:0}],en:[{t:"One"},{t:"is not allowed to smoke",g:0},{t:"here",g:1}],hi:[{t:"यहाँ",g:1},{t:"धूम्रपान करना मना है",g:0}],hiTranslit:"yahaan dhoomrapaan karna mana hai",note:'German man and English "one" both need an explicit generic subject; Hindi expresses the same impersonal meaning with no subject at all.'}]},{id:"pron-jemand",category:"pronoun",de:"jemand",en:["someone","somebody"],hi:["कोई"],hiTranslit:"koi",ipa:"ˈjeːmant",deva:"येमन्ट्",level:"A2",illustration:"pron-jemand",type:"indefinite",notes:"jemand refers to an unspecified person and takes a singular verb; unlike man, it can appear in any grammatical case (jemanden, jemandem) and isn't restricted to subject position.",examples:[{de:[{t:"Jemand",g:0},{t:"hat angerufen",g:1}],en:[{t:"Someone",g:0},{t:"called",g:1}],hi:[{t:"किसी ने",g:0},{t:"फ़ोन किया",g:1}],hiTranslit:"kisi ne phone kiya",note:"German forms the past with haben + angerufen (Perfekt); Hindi marks the same past action with the ergative-like ने plus a simple past verb."}]},{id:"pron-niemand",category:"pronoun",de:"niemand",en:["no one","nobody"],hi:["कोई नहीं"],hiTranslit:"koi nahin",ipa:"ˈniːmant",deva:"नीमन्ट्",level:"A2",illustration:"pron-niemand",type:"indefinite",notes:'niemand is the negative counterpart of jemand; German needs only this one word for "nobody," while Hindi builds the same meaning from कोई ("someone") plus नहीं ("not").',examples:[{de:[{t:"Niemand",g:0},{t:"hat",g:1},{t:"mir",g:2},{t:"geholfen",g:1}],en:[{t:"Nobody",g:0},{t:"helped",g:1},{t:"me",g:2}],hi:[{t:"किसी ने",g:0},{t:"मेरी",g:2},{t:"मदद नहीं की",g:1}],hiTranslit:"kisi ne meri madad nahin ki",note:'German packs the negation into niemand itself; Hindi needs a separate word नहीं alongside कोई to express the same "nobody".'}]},{id:"pron-etwas",category:"pronoun",de:"etwas",en:["something","anything"],hi:["कुछ"],hiTranslit:"kuch",ipa:"ˈɛtvas",deva:"एट्वस्",level:"A2",illustration:"pron-etwas",type:"indefinite",notes:'etwas is invariant — it never changes for case, gender, or number; Hindi कुछ behaves exactly the same way, while English alternates between "something" and "anything" depending on context.',examples:[{de:[{t:"Ich habe",g:0},{t:"etwas",g:1},{t:"für dich",g:2}],en:[{t:"I have",g:0},{t:"something",g:1},{t:"for you",g:2}],hi:[{t:"मेरे पास",g:0},{t:"तुम्हारे लिए",g:2},{t:"कुछ है",g:1}],hiTranslit:"mere paas tumhaare liye kuch hai",note:'German "to have" uses haben in a subject-first construction; Hindi instead uses a possessive-locative construction ("in my vicinity there is") with no verb "to have" at all.'}]},{id:"pron-nichts",category:"pronoun",de:"nichts",en:["nothing"],hi:["कुछ नहीं"],hiTranslit:"kuch nahin",ipa:"nɪçts",deva:"निख़्ट्स्",level:"A2",illustration:"pron-nichts",type:"indefinite",notes:'nichts is the negative counterpart of etwas; like niemand, German expresses it in one word while Hindi needs two, कुछ नहीं ("something not").',examples:[{de:[{t:"Ich",g:0},{t:"habe",g:1},{t:"nichts",g:2},{t:"gesagt",g:1}],en:[{t:"I",g:0},{t:"said",g:1},{t:"nothing",g:2}],hi:[{t:"मैंने",g:0},{t:"कुछ नहीं",g:2},{t:"कहा",g:1}],hiTranslit:"mainne kuch nahin kaha",note:"German splits the Perfekt tense across habe...gesagt with nichts in between; Hindi and English both keep their single past-tense verb together as one word."}]},{id:"pron-jeder",category:"pronoun",de:"jeder",en:["every","each (masculine, nominative)"],hi:["हर","हर एक"],hiTranslit:"har / har ek",ipa:"ˈjeːdɐ",deva:"येडा",level:"A2",illustration:"pron-jeder",type:"indefinite",gender:"m",notes:'jeder declines like dieser (jeder/jede/jedes) and is always used with a singular noun, even though it implies "all of them, one by one"; Hindi हर is invariant regardless of gender.',examples:[{de:[{t:"Jeder Schüler",g:0},{t:"braucht",g:1},{t:"ein Buch",g:2}],en:[{t:"Every student",g:0},{t:"needs",g:1},{t:"a book",g:2}],hi:[{t:"हर छात्र को",g:0},{t:"एक किताब",g:2},{t:"चाहिए",g:1}],hiTranslit:"har chhaatra ko ek kitaab chahiye",note:`German and English treat "need" as an ordinary transitive verb with the person as subject; Hindi's चाहिए construction instead makes the needed thing the grammatical subject.`}]},{id:"pron-alle",category:"pronoun",de:"alle",en:["all","everyone","everybody"],hi:["सब","सभी"],hiTranslit:"sab / sabhi",ipa:"ˈalə",deva:"अले",level:"A2",illustration:"pron-alle",type:"indefinite",number:"pl",notes:"alle is the plural counterpart to jeder's singular — both express totality, but alle takes a plural verb while jeder takes a singular one.",examples:[{de:[{t:"Alle",g:0},{t:"sind eingeladen",g:1}],en:[{t:"Everyone",g:0},{t:"is invited",g:1}],hi:[{t:"सबको",g:0},{t:"आमंत्रित किया गया है",g:1}],hiTranslit:"sabko aamantrit kiya gaya hai",note:"German alle takes a plural verb (sind), matching its plural sense, while Hindi सबको pairs with a singular passive verb form instead."}]},{id:"pron-einige",category:"pronoun",de:"einige",en:["some","a few"],hi:["कुछ","कई"],hiTranslit:"kuch / kai",ipa:"ˈaɪnɪɡə",deva:"आइनिगे",level:"B1",illustration:"pron-einige",type:"indefinite",number:"pl",notes:`einige refers to an unspecified small number and is always plural; Hindi's कुछ covers both "some" (plural) and "something" (etwas), so context alone decides which German word it maps to.`,examples:[{de:[{t:"Einige Studenten",g:0},{t:"waren",g:1},{t:"spät",g:2}],en:[{t:"Some students",g:0},{t:"were",g:1},{t:"late",g:2}],hi:[{t:"कुछ छात्र",g:0},{t:"देर से",g:2},{t:"आए",g:1}],hiTranslit:"kuch chhaatra der se aaye",note:'All three languages put the subject first here, but Hindi folds "were late" into a single verb aaye ("came [late]") rather than pairing a copula with an adjective.'}]},{id:"pron-kein",category:"pronoun",de:"kein",en:["no","not a/any"],hi:["कोई नहीं"],hiTranslit:"koi nahin",ipa:"kaɪn",deva:"काइन्",level:"A1",illustration:"pron-kein",type:"indefinite",notes:`kein negates an indefinite or unmarked noun (kein Auto = "no car") and declines like ein — a single word doing the work of English "no" plus Hindi's separate कोई...नहीं.`,examples:[{de:[{t:"Ich",g:0},{t:"habe",g:2},{t:"kein Auto",g:1}],en:[{t:"I",g:0},{t:"don't have",g:2},{t:"a car",g:1}],hi:[{t:"मेरे पास",g:0},{t:"कोई गाड़ी नहीं",g:1},{t:"है",g:2}],hiTranslit:"mere paas koi gaadi nahin hai",note:'German negates the object itself with kein, and Hindi negates the object phrase with नहीं too; English instead negates the verb "have" directly.'}]}];export{e as pronouns};
